def max_tandem_repeat_length(s, k):
    n = len(s)
    max_l = 0

    # Check for possible tandem repeats in the original string
    for i in range(n):
        for j in range(i + 1, n):
            length = j - i
            if length * 2 > max_l and s[i:j] == s[j:j + length]:
                is_tandem_repeat = True
                for offset in range(1, length):
                    if s[i:i + offset] != s[j:j + offset]:
                        is_tandem_repeat = False
                        break
                if is_tandem_repeat:
                    max_l = length * 2

    # If k is 0, return the maximum length found so far
    if k == 0:
        return max_l

    # Now consider the possible tandem repeats with the k added characters
    # Since Kolya added k characters, the maximum tandem repeat length is determined by the original string length
    max_l = max(max_l, n * 2)

    return max_l

