def max_tandem_repeat_length(s: str, k: int) -> int:
    n = len(s)
    max_l = 0

    # Try to find the longest tandem repeat for each possible center of the tandem repeat
    for center in range(n):
        # Check for odd length tandem repeats
        l = 1
        while center - l >= 0 and center + l < n + k:
            if s[center - l] == s[center + l]:
                l += 1
            else:
                break
        max_l = max(max_l, 2 * (l - 1))

        # Check for even length tandem repeats
        if center < n - 1:
            l = 0
            while center - l >= 0 and center + 1 + l < n + k:
                if s[center - l] == s[center + 1 + l]:
                    l += 1
                else:
                    break
            max_l = max(max_l, 2 * l)

    return max_l

